@startuml

class User {
  + id : string
  + name : string
  + address : string
  + birthday : date
}

class BusinessOwner extends User {
  + linkedin_account : string
}

class PizzaRestaurant {
  + zip_code : string
  + address : string
  + phone_number : string
  + website : string
  + opening_hours : string
}

class Pizza {
  + name : string
  + crust_structure : string
  + price : double
}

class HungryCustomer extends User {
  + delivery_address : string
}

class Order {
  + id : string
  + date_time : datetime
  + latest_delivery_time : time
  + number_of_people : int
}

class EntertainmentOrder extends Order {
  + entertainment_type : string
  + duration : time
}

class Entertainer extends User {
  + stage_name : string
  + bio : string
  + price_per_30_min : double
}

class Availability {
  + day : string
}

BusinessOwner "1" *-- "*" PizzaRestaurant
PizzaRestaurant "1" -- "*" Pizza
HungryCustomer "1" -- "*" Order
Order "1" -- "1..*" Pizza
EntertainmentOrder "*" -- "1" Entertainer
Entertainer "1" -- "*" Availability
Availability "*" -- "1" PizzaRestaurant

@enduml

